import pandas as pd
import numpy as np


def _is_null(v):
    if v is None:
        return True
    try:
        if isinstance(v, float) and np.isnan(v):
            return True
    except TypeError:
        pass
    if v is pd.NaT:
        return True
    try:
        if pd.isna(v):
            return True
    except (TypeError, ValueError):
        pass
    return False


def _changed(old, new):
    old_null = _is_null(old)
    new_null = _is_null(new)
    if old_null and new_null:
        return False
    if old_null != new_null:
        return True
    return old != new


def run(inputs: dict) -> dict:
    dim = inputs["DIM_PRODUCT"].copy()
    stg = inputs["STG_PRODUCT"].copy()

    # Normalize dim product rows into list of dict, grouped by product_id
    dim_cols = ["product_id", "category", "price_band",
                "eff_start_date", "eff_end_date", "is_current"]

    # Ensure columns exist even if dim is empty
    for c in dim_cols:
        if c not in dim.columns:
            dim[c] = pd.Series(dtype=object)

    products_rows = {}
    current_rows = {}

    for _, row in dim.iterrows():
        pid = row["product_id"]
        rec = {
            "product_id": row["product_id"],
            "category": row["category"],
            "price_band": row["price_band"],
            "eff_start_date": row["eff_start_date"],
            "eff_end_date": row["eff_end_date"],
            "is_current": row["is_current"],
        }
        products_rows.setdefault(pid, []).append(rec)
        if _is_null(rec["is_current"]) is False and rec["is_current"] == 1:
            current_rows[pid] = rec

    # Sort staged records by product_id, update_date ascending (cursor order)
    if not stg.empty:
        stg_sorted = stg.sort_values(by=["product_id", "update_date"],
                                      kind="mergesort").reset_index(drop=True)
    else:
        stg_sorted = stg

    for _, srow in stg_sorted.iterrows():
        pid = srow["product_id"]
        s_cat = srow["category"]
        s_band = srow["price_band"]
        s_date = srow["update_date"]

        current = current_rows.get(pid)

        if current is None:
            new_rec = {
                "product_id": pid,
                "category": s_cat,
                "price_band": s_band,
                "eff_start_date": s_date,
                "eff_end_date": None,
                "is_current": 1,
            }
            products_rows.setdefault(pid, []).append(new_rec)
            current_rows[pid] = new_rec
        else:
            cat_changed = _changed(current["category"], s_cat)
            band_changed = _changed(current["price_band"], s_band)
            if cat_changed or band_changed:
                current["eff_end_date"] = s_date
                current["is_current"] = 0

                new_rec = {
                    "product_id": pid,
                    "category": s_cat,
                    "price_band": s_band,
                    "eff_start_date": s_date,
                    "eff_end_date": None,
                    "is_current": 1,
                }
                products_rows.setdefault(pid, []).append(new_rec)
                current_rows[pid] = new_rec
            # else: no-op

    all_recs = []
    for pid, recs in products_rows.items():
        all_recs.extend(recs)

    out_df = pd.DataFrame(all_recs, columns=dim_cols)

    if not out_df.empty:
        out_df["product_id"] = out_df["product_id"].astype(dim["product_id"].dtype
                                                             if not dim.empty else "int64")
        out_df["is_current"] = out_df["is_current"].astype("int64")

        out_df["eff_start_date"] = pd.to_datetime(out_df["eff_start_date"])
        out_df["eff_end_date"] = pd.to_datetime(out_df["eff_end_date"])

    return {"dim_product_out": out_df}
